/** One class of a classed scale (spec/01 §8.1): values from [from] on, up to the next class; [label] its range. */
@Immutable
data class SbScaleClass(val from: Float, val label: String)

/**
 * One day of a heatmap: [day] spelled out („Mittwoch, 21.10.“), [value] (null = keine Angabe), [valueText] the value
 * with its unit („7 Gläser“, „1 Glas“), [today] = the cobalt frame of D93.
 */
@Immutable
data class SbHeatmapDay(val day: String, val value: Float?, val valueText: String = "", val today: Boolean = false)

/** One week row: [start] = its first date („28.09.“, shown as „ab 28.09.“), [days] one per weekday head, null = to come. */
@Immutable
data class SbHeatmapWeek(val start: String, val days: List<SbHeatmapDay?>)

/**
 * Heatmap (G6a, spec/02 §3.7): the legend above with the range of every class, „keine Angabe“ and „Rahmen: heute“;
 * weekday heads over one row per week; square cells 6 dp apart in the classes of dataviz.sequential (no number on the
 * fill); a day without a value is the empty cell with a 1 dp borderStrong frame; today is the 4 dp accent frame on
 * the cell's edge with a 1 dp bg joint inside (D93); focus is the square 2 dp ring outside the cell (§3). One
 * TalkBack sentence per day; arrows, Home and End move by day and week as sb-chart.js; the read-out under the grid
 * shows the focused or tapped day, else [hint] (D99 (7): by default the words table's „Tipp auf einen Tag, um seinen
 * Wert zu sehen.“; the app may pass its own sentence). [weekdays] = the heads in the order of [SbHeatmapWeek.days].
 * [legendLabel] names the legend for TalkBack („Legende, Gläser je Tag“; then the legend is one node).
 */
@Composable
fun SbHeatmap(
    weeks: List<SbHeatmapWeek>,
    classes: List<SbScaleClass>,
    caption: String,
    modifier: Modifier = Modifier,
    hint: String = sbMessages().heatmapHint,
    weekdays: List<String> = sbMessages().weekdays,
    legendLabel: String? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val measurer = rememberTextMeasurer()
    val scale = SebaroTheme.dataviz.sequential
    require(classes.size in 1..scale.size) { "SbHeatmap: 1 to ${scale.size} classes (spec/01 §8.1)" }
    require(classes.zipWithNext().all { (a, b) -> a.from < b.from }) { "SbHeatmap: the classes must rise" }
    require(weeks.all { it.days.size == weekdays.size }) { "SbHeatmap: every week has one entry per weekday head" }
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val gap = t.space.s1 + t.space.s0_5
    val rem = sbTextScale()
    val headWidth = (t.space.s16 + t.space.s2) * rem
    val line = with(LocalDensity.current) { ty.caption.lineHeight.toDp() }
    val rtl = LocalLayoutDirection.current == LayoutDirection.Rtl
    val radius = t.radius.small
    // the days in reading order; index[w][d] = a day's place in it, -1 for a day still to come
    val days = remember(weeks) { weeks.flatMap { it.days.filterNotNull() } }
    val index = remember(weeks) {
        var n = 0
        weeks.map { w -> w.days.map { if (it == null) -1 else n++ } }
    }
    val requesters = remember(days.size) { List(days.size) { FocusRequester() } }
    var focused by remember { mutableStateOf<Int?>(null) }
    var tapped by remember { mutableStateOf<Int?>(null) }
    fun classOf(v: Float) = classes.indexOfLast { it.from <= v }.coerceAtLeast(0)
    fun sentence(d: SbHeatmapDay) = m.chartDay(d.day, if (d.value == null) m.noValue else d.valueText, d.today)
    SbChartFigure(
        caption,
        modifier,
        legend = {
            // named (the web's aria-label on the list): one node, the label first, then every key's word
            val keys = classes.map { it.label } + m.noValue + m.todayKey
            SbFlowRow(
                modifier = if (legendLabel == null) Modifier else Modifier.clearAndSetSemantics {
                    contentDescription = (listOf(legendLabel) + keys).joinToString(", ")
                },
                horizontalArrangement = Arrangement.spacedBy(t.space.s4),
                verticalArrangement = Arrangement.spacedBy(t.space.s1),
            ) {
                classes.forEachIndexed { i, k ->
                    SbScaleKey(k.label) { drawSbScaleCell(scale[i], c.borderStrong, null, c.bg, radius.toPx(), t.borderWidth.hairline.toPx(), t.borderWidth.strong.toPx()) }
                }
                SbScaleKey(m.noValue) { drawSbScaleCell(null, c.borderStrong, null, c.bg, radius.toPx(), t.borderWidth.hairline.toPx(), t.borderWidth.strong.toPx()) }
                SbScaleKey(m.todayKey) { drawSbScaleCell(null, null, c.accent, c.bg, radius.toPx(), t.borderWidth.hairline.toPx(), t.borderWidth.strong.toPx()) }
            }
        },
    ) {
        Column(
            Modifier
                // the web's 26rem holds the two outer gaps of its border-spacing as well
                .widthIn(max = (t.space.s16 * 6 + t.space.s8) * rem - gap * 2)
                .fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(gap),
        ) {
            // D104 (21), BA-1 (per D103 the simpler form; provisional, agent): the heads keep their two letters (D82).
            // Each head is measured against its own column (cell + gap); once a two-letter head does not fit its
            // column, every second head is left out („Mo Mi Fr So“, the web's nth-of-type(even)), so a shown head has
            // the empty room of its neighbours. A shown head stays whole and centred over its cell, never broken, the
            // last one moved back to end with the grid; the day's TalkBack sentence names every day. Until D104 every
            // head took a one-letter form here (§14.11, D102 lane narrow)
            val headWidths = remember(weekdays, text, measurer) {
                weekdays.map { measurer.measure(it, text, softWrap = false, maxLines = 1).size.width }
            }
            BoxWithConstraints(Modifier.fillMaxWidth()) {
                val density = LocalDensity.current
                val room = constraints.maxWidth.toFloat()
                val g = with(density) { gap.toPx() }
                val cell = with(density) { (room - headWidth.toPx() - weekdays.size * g) / weekdays.size }
                val centres = with(density) { weekdays.indices.map { headWidth.toPx() + g + it * (cell + g) + cell / 2f } }
                val thin = headWidths.any { it > cell + g }
                Row(
                    Modifier
                        .fillMaxWidth()
                        .clearAndSetSemantics { },
                    horizontalArrangement = Arrangement.spacedBy(gap),
                ) {
                    Spacer(Modifier.width(headWidth))
                    weekdays.forEachIndexed { i, head ->
                        Text(
                            head,
                            style = text,
                            color = c.textMuted,
                            softWrap = false,
                            modifier = Modifier
                                .weight(1f)
                                .wrapContentWidth(unbounded = true)
                                .offset { IntOffset(-(centres[i] + headWidths[i] / 2f - room).coerceAtLeast(0f).roundToInt(), 0) }
                                .alpha(if (thin && i % 2 == 1) 0f else 1f),
                        )
                    }
                }
            }
            weeks.forEachIndexed { w, week ->
                Row(
                    Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(gap),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    // D99 (1): a week head that does not fit its column wraps between words („from / 28 Sep“)
                    SbWrapText(
                        m.weekFrom(week.start),
                        text,
                        c.textMuted,
                        Modifier
                            .width(headWidth)
                            .clearAndSetSemantics { },
                    )
                    week.days.forEachIndexed { d, day ->
                        val k = index[w][d]
                        if (day == null) {
                            Spacer(
                                Modifier
                                    .weight(1f)
                                    .aspectRatio(1f),
                            )
                        } else {
                            val interaction = remember { MutableInteractionSource() }
                            val fill = day.value?.let { scale[classOf(it)] }
                            Box(
                                Modifier
                                    .weight(1f)
                                    .aspectRatio(1f)
                                    .sbFocusRing(interaction, RectangleShape)
                                    .focusRequester(requesters[k])
                                    .onFocusChanged { if (it.isFocused) focused = k else if (focused == k) focused = null }
                                    .onPreviewKeyEvent { e ->
                                        // as sb-chart.js: Alt and Meta pass, Ctrl only goes with Home and End
                                        if (e.type != KeyEventType.KeyDown || e.isAltPressed || e.isMetaPressed) return@onPreviewKeyEvent false
                                        val inWeek = index[w].filter { it >= 0 }
                                        val to: Int? = when (e.key) {
                                            Key.DirectionRight -> if (e.isCtrlPressed) return@onPreviewKeyEvent false else k + (if (rtl) -1 else 1)
                                            Key.DirectionLeft -> if (e.isCtrlPressed) return@onPreviewKeyEvent false else k + (if (rtl) 1 else -1)
                                            Key.DirectionDown -> if (e.isCtrlPressed) return@onPreviewKeyEvent false else sbHeatmapSameWeekday(index, w, d, 1)
                                            Key.DirectionUp -> if (e.isCtrlPressed) return@onPreviewKeyEvent false else sbHeatmapSameWeekday(index, w, d, -1)
                                            Key.MoveHome -> if (e.isCtrlPressed) 0 else inWeek.first()
                                            Key.MoveEnd -> if (e.isCtrlPressed) days.lastIndex else inWeek.last()
                                            else -> return@onPreviewKeyEvent false
                                        }
                                        // no day that way: Compose's focus search takes the key, so a D-pad without
                                        // Tab can leave the grid at its edges (the web keeps it: there Tab leaves)
                                        if (to == null || to !in days.indices) return@onPreviewKeyEvent false
                                        if (to != k) requesters[to].requestFocus()
                                        true
                                    }
                                    .focusable(interactionSource = interaction)
                                    .pointerInput(k) { detectTapGestures(onTap = { tapped = k }) }
                                    .semantics { contentDescription = sentence(day) }
                                    .drawBehind {
                                        drawSbScaleCell(
                                            fill,
                                            if (day.value == null) c.borderStrong else null,
                                            if (day.today) c.accent else null,
                                            c.bg,
                                            radius.toPx(),
                                            t.borderWidth.hairline.toPx(),
                                            t.borderWidth.strong.toPx(),
                                        )
                                    },
                            )
                        }
                    }
                }
            }
        }
        val shown = (focused ?: tapped)?.let { days.getOrNull(it) }
        Text(
            shown?.let { sentence(it) } ?: hint,
            style = text,
            color = c.text,
            modifier = Modifier
                .heightIn(min = line)
                .clearAndSetSemantics { },
        )
    }
}

/** The same weekday [dir] weeks on (±1), skipping days still to come; null at the first or last week. */
private fun sbHeatmapSameWeekday(index: List<List<Int>>, w: Int, d: Int, dir: Int): Int? {
    var row = w + dir
    while (row in index.indices) {
        val k = index[row][d]
        if (k >= 0) return k
        row += dir
    }
    return null
}

/** A legend key: the 16 dp swatch drawn by [draw], then its word in caption, one TalkBack node. */
@Composable
private fun SbScaleKey(label: String, draw: DrawScope.() -> Unit) {
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    Row(
        Modifier.semantics(mergeDescendants = true) { },
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s2),
    ) {
        Canvas(Modifier.size(t.size.iconSm), onDraw = draw)
        Text(label, style = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings), color = SebaroTheme.colors.text)
    }
}

/**
 * One scale cell or swatch: [fill] (a class colour), else the 1 dp [frame] of „keine Angabe“ (null: nothing); with
 * [today] the 4 dp frame (strong + hairline) on the edge, rounded like the cell, and the 1 dp [joint] inside it (D93).
 */
private fun DrawScope.drawSbScaleCell(
    fill: Color?,
    frame: Color?,
    today: Color?,
    joint: Color,
    radius: Float,
    hairline: Float,
    strong: Float,
) {
    if (fill != null) {
        drawRoundRect(fill, cornerRadius = CornerRadius(radius))
    } else if (frame != null && today == null) {
        drawRoundRect(
            frame,
            topLeft = Offset(hairline / 2f, hairline / 2f),
            size = Size(size.width - hairline, size.height - hairline),
            cornerRadius = CornerRadius(max(radius - hairline / 2f, 0f)),
            style = Stroke(hairline),
        )
    }
    if (today != null) {
        val f = strong + hairline
        drawRoundRect(
            today,
            topLeft = Offset(f / 2f, f / 2f),
            size = Size(size.width - f, size.height - f),
            cornerRadius = CornerRadius(max(radius - f / 2f, 0f)),
            style = Stroke(f),
        )
        drawRect(
            joint,
            topLeft = Offset(f + hairline / 2f, f + hairline / 2f),
            size = Size(size.width - 2 * f - hairline, size.height - 2 * f - hairline),
            style = Stroke(hairline),
        )
    }
}
